import * as util from "node:util";
import { setTimeout as st } from "node:timers/promises";
function cb(a: number, f: (e: Error | null, r?: number) => void) { setImmediate(() => f(null, a * 2)); }
const p = util.promisify(cb);
async function run() {
  console.log(await p(2));
  console.log(await st(1, "v"));
  setTimeout(() => console.log("global timer still works"), 1);
}
function main(): void { run(); }
